SELECT
  ID AS id,
  NAME AS name,
  EMAIL
FROM T_USER
WHERE ID NOT IN (
  SELECT FollowingID FROM T_TRACE_FOLLOWS WHERE FollowerID = #{id}
)
AND ID != #{id}
